select jsonb_build_object('scope','exact-protected-dashboard-reader-prerequisites',
 'schema',(select jsonb_build_object('owner',r.rolname,'acl',n.nspacl::text,
 'reader_usage',has_schema_privilege('custodial_application_reader',n.oid,'USAGE'),
 'reader_create',has_schema_privilege('custodial_application_reader',n.oid,'CREATE'),
 'anon_usage',has_schema_privilege('anon',n.oid,'USAGE'),
 'authenticated_usage',has_schema_privilege('authenticated',n.oid,'USAGE'),
 'service_usage',has_schema_privilege('service_role',n.oid,'USAGE'))
 from pg_namespace n join pg_roles r on r.oid=n.nspowner where n.nspname='custodial_release_identity'),
 'columns',(select jsonb_agg(to_jsonb(c) order by relation_name,column_name) from columns c),
 'missing_columns',(select coalesce(jsonb_agg(to_jsonb(c) order by relation_name,column_name),'[]'::jsonb) from columns c where not present),
 'protected_relations',(select jsonb_agg(jsonb_build_object('identity',c.oid::regclass::text,'owner',r.rolname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity))
 from pg_class c join pg_roles r on r.oid=c.relowner where c.oid in(to_regclass('public.sessions'),to_regclass('public.completion_responses'))));
